<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;
class AdminAppointmentController { public function index(){ $this->guard();$appointments=DB::table('appointments')->latest('appointment_at')->get();foreach($appointments as $appointment){$appointment->patient_name.=' — '.($appointment->source_type==='healthcare_provider'?'Healthcare Provider':'Patient');}return view('admin-appointments',['appointments'=>$appointments]); } public function update(Request $request,$id){$this->guard();$data=$request->validate(['date'=>'required|date','slot'=>'required|in:00:00,02:00,04:00,06:00,08:00,10:00,12:00','status'=>'required|in:pending,confirmed,cancelled']);$appointmentAt=$data['date'].' '.$data['slot'];abort_if(DB::table('appointments')->where('id','!=',$id)->where('appointment_at',$appointmentAt)->where('status','!=','cancelled')->exists(),422,'This time slot has already been booked.');DB::table('appointments')->where('id',$id)->update(['appointment_at'=>$appointmentAt,'status'=>$data['status'],'updated_at'=>now()]);return back()->with('success','Appointment updated.');} private function guard(){abort_unless(Auth::check()&&Auth::user()->is_admin,403);} }
